window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66ff0e305612c605"]={"versions": [{"id": "FIG-66ff0e305612c605", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code></li>\n<li><strong>Eingangsparameter</strong>:</li>\n<li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).</li>\n<li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (Payload/Header).</li>\n<li><code>Length</code>: Länge der übergebenen Daten in Byte.</li>\n<li><strong>Knotenelemente</strong>:</li>\n<li>Initialknoten (Startpunkt der Prüfung).</li>\n<li>Zwei Entscheidungsknoten (Rauten) zur sequenziellen Validierung von Zeigern und Datenlänge.</li>\n<li>Drei Aktivitätsendknoten (<code>no input</code>, <code>input ok</code>, <code>wrong input</code>), korrespondierend zu den Fehler- bzw. Erfolgszuständen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.</li>\n<li>Erste Prüfung am oberen Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no input</code> (führt im übergeordneten Ablauf zu <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Übergang zur nachfolgenden Längenprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Prüfung am unteren Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>Length == Config-&gt;DataLength/8</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code> (führt im übergeordneten Ablauf zu <code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input ok</code> (erlaubt die Fortsetzung der Schutzfunktion mit Write Counter, CRC-Berechnung etc.).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\">\n<li>Zeiger dürfen nicht <code>NULL</code> sein, andernfalls ist die Ausführung sofort mit Null-Pointer-Fehler zu beenden.</li>\n<li>Die übergebene Bytezahl <code>Length</code> muss exakt der in <code>Config-&gt;DataLength</code> spezifizierten Bitlänge dividiert durch 8 entsprechen.</li>\n<li>Bei abweichender Länge darf keine Manipulation oder Berechnung auf dem Puffer erfolgen; es ist zwingend der Fehlerstatus für inkorrekte Eingaben zurückzugeben.</li>\n</ul>"}, {"id": "FIG-13a23f18d89df96e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code></li>\n<li><strong>Eingangsparameter</strong>:</li>\n<li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).</li>\n<li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array.</li>\n<li><code>Length</code>: Länge der Daten in Byte.</li>\n<li><code>Offset</code>: Offset-Position des Headers in Byte (implizit/aus Konfiguration referenziert).</li>\n<li><strong>Knotenelemente</strong>:</li>\n<li>Initialknoten.</li>\n<li>Zwei Entscheidungsknoten (Rauten) zur Zeiger- und Bereichsprüfung.</li>\n<li>Drei Aktivitätsendknoten (<code>no</code>, <code>input</code>, <code>wrong</code>), repräsentierend <code>no input</code>, <code>input ok</code> und <code>wrong input</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.</li>\n<li>Erste Prüfung am oberen Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no</code> (entspricht <code>no input</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Weiterleitung zur kombinierten Längenprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Prüfung am unteren Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong</code> (entspricht <code>wrong input</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input</code> (entspricht <code>input ok</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\">\n<li>Zeiger dürfen nicht <code>NULL</code> sein.</li>\n<li>Die übergebene Länge <code>Length</code> muss strikt gleich <code>Config-&gt;DataLength/8</code> sein und muss zusätzlich mindestens <code>Offset + 2</code> Byte umfassen, um sicherzustellen, dass die CRC- und Counter-Felder innerhalb der übergebenen Puffergrenzen liegen.</li>\n<li>Eine Verletzung einer der beiden Längenbedingungen führt zwingend zur Beendigung über den Pfad <code>wrong input</code>.</li>\n</ul>"}, {"id": "FIG-489a823a15b84774", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code></li>\n<li><strong>Eingangsparameter</strong>:</li>\n<li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).</li>\n<li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array.</li>\n<li><code>Length</code>: Länge der Daten in Byte.</li>\n<li><code>Offset</code>: Offset-Position des Headers in Byte (implizit/aus Konfiguration referenziert).</li>\n<li><strong>Knotenelemente</strong>:</li>\n<li>Initialknoten.</li>\n<li>Zwei Entscheidungsknoten (Rauten) zur Zeiger- und Bereichsprüfung.</li>\n<li>Drei Aktivitätsendknoten (<code>no</code>, <code>input</code>, <code>wrong</code>), repräsentierend <code>no input</code>, <code>input ok</code> und <code>wrong input</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.</li>\n<li>Erste Prüfung am oberen Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no</code> (entspricht <code>no input</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Weiterleitung zur kombinierten Längenprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Prüfung am unteren Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong</code> (entspricht <code>wrong input</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input</code> (entspricht <code>input ok</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\">\n<li>Zeiger dürfen nicht <code>NULL</code> sein.</li>\n<li>Die übergebene Länge <code>Length</code> muss strikt gleich <code>Config-&gt;DataLength/8</code> sein und muss zusätzlich mindestens <code>Offset + 2</code> Byte umfassen, um sicherzustellen, dass die CRC- und Counter-Felder innerhalb der übergebenen Puffergrenzen liegen.</li>\n<li>Eine Verletzung einer der beiden Längenbedingungen führt zwingend zur Beendigung über den Pfad <code>wrong input</code>.</li>\n</ul>"}, {"id": "FIG-beeac12caf55f8ef", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code></li>\n<li><strong>Eingangsparameter</strong>:</li>\n<li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).</li>\n<li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array.</li>\n<li><code>Length</code>: Länge der Daten in Byte.</li>\n<li><code>Offset</code>: Offset-Position des Headers in Byte (implizit/aus Konfiguration referenziert).</li>\n<li><strong>Knotenelemente</strong>:</li>\n<li>Initialknoten.</li>\n<li>Zwei Entscheidungsknoten (Rauten) zur Zeiger- und Bereichsprüfung.</li>\n<li>Drei Aktivitätsendknoten (<code>no</code>, <code>input</code>, <code>wrong</code>), repräsentierend <code>no input</code>, <code>input ok</code> und <code>wrong input</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.</li>\n<li>Erste Prüfung am oberen Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no</code> (entspricht <code>no input</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Weiterleitung zur kombinierten Längenprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Prüfung am unteren Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2</code></li>\n<li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong</code> (entspricht <code>wrong input</code>).</li>\n<li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input</code> (entspricht <code>input ok</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\">\n<li>Zeiger dürfen nicht <code>NULL</code> sein.</li>\n<li>Die übergebene Länge <code>Length</code> muss strikt gleich <code>Config-&gt;DataLength/8</code> sein und muss zusätzlich mindestens <code>Offset + 2</code> Byte umfassen, um sicherzustellen, dass die CRC- und Counter-Felder innerhalb der übergebenen Puffergrenzen liegen.</li>\n<li>Eine Verletzung einer der beiden Längenbedingungen führt zwingend zur Beendigung über den Pfad <code>wrong input</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-66ff0e305612c605", "to": "FIG-13a23f18d89df96e", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Entscheidungsknoten zur Längenprüfung: Die Verzweigungsbedingung wurde von <code>Length == Config-&gt;DataLength/8</code> um die zusätzliche Konjunktion <code>&amp;&amp; Length &gt;= Offset+2</code> erweitert.</li>\n<li>Layout / Beschriftungsplatzierung: Die Guard-Bedingungen <code>[FALSE]</code> wurden näher an die Rauten bzw. Pfadursprünge gerückt und Bedingungen mehrzeilig umbrochen.</li>\n<li>Endknoten-Beschriftungen: Die Bezeichner an den Activity-Final-Knoten wurden im Bildbeschnitt teils verkürzt/umgebrochen dargestellt (<code>no input</code> -> <code>no</code>, <code>input ok</code> -> <code>input</code>, <code>wrong input</code> -> <code>wrong</code>).</li>\n</ul>"}, {"from": "FIG-13a23f18d89df96e", "to": "FIG-489a823a15b84774", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-489a823a15b84774", "to": "FIG-beeac12caf55f8ef", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
